/* ==========================================================
   ALEX GONZALEZ / ENGINEERING — DAMASCUS PORTFOLIO
   ==========================================================
   COLORS: Change these values to update the entire theme.
   BACKGROUND: Replace assets/damascus-background.webp.
   ========================================================== */

:root {
    --charcoal: #1f1f1f;
    --dark-grey: #2e2e2e;
    --gold: #e5a83b;
    --antique-gold: #b8860b;
    --cream: #efebe4;
    --muted: #b9b8b7;
    --line: rgba(229, 168, 59, 0.38);
    --content-width: 1400px;
}

/* BASE --------------------------------------------------- */

* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    scroll-padding-top: 90px;
}

body {
    margin: 0;
    background: #111111;
    isolation: isolate;
    min-height: 100vh;
    color: var(--cream);
    font-family: "Segoe UI", Arial, sans-serif;
    line-height: 1.6;
}

a {
    color: inherit;
    text-decoration: none;
}

button {
    font: inherit;
}

button,
a {
    -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible {
    outline: 2px solid var(--gold);
    outline-offset: 4px;
}

.container {
    width: min(calc(100% - 64px), var(--content-width));
    margin-inline: auto;
}

.gold {
    color: var(--gold);
}

.eyebrow {
    color: var(--gold);
    text-transform: uppercase;
    letter-spacing: 0.28em;
    font-size: 12px;
    font-weight: 600;
}

/* DAMASCUS BACKGROUND ----------------------------------- */
/* The *entire* approved artwork is placed behind the page once.
   It covers the viewport rather than repeating across cards/sections.
   The 2x image provides additional delivery pixels for HiDPI displays.
   For easier customization, change only the URL below. */

body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background-color: #111111;
    background-image: url("data:image/webp;base64,");
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
}

/* Keep the shared background visible below each page's content. */
body > * {
    position: relative;
    z-index: 1;
}

.damascus-surface {
    background-color: transparent;
    background-image: none;
}

/* HEADER ------------------------------------------------ */

.site-header {
    position: relative;
    z-index: 10;
    background: rgba(12, 12, 12, 0.98);
    border-bottom: 1px solid rgba(229, 168, 59, 0.16);
}

.nav-row {
    min-height: 84px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 28px;
}

.brand {
    display: inline-block;
    font-size: clamp(13px, 1.35vw, 20px);
    font-weight: 700;
    letter-spacing: 0.13em;
    text-transform: uppercase;
    white-space: nowrap;
}

.brand > span:first-child,
.brand-slash {
    color: var(--gold);
}

.brand-muted {
    color: var(--muted);
    font-weight: 400;
}

.main-nav {
    display: flex;
    align-items: center;
    gap: clamp(8px, 1.7vw, 28px);
}

.nav-link {
    padding: 12px 10px;
    position: relative;
    isolation: isolate;
    overflow: hidden;
    font-size: 11px;
    letter-spacing: 0.19em;
    text-transform: uppercase;
    /* Hover text transitions are defined in the animation section. */
}

/* Interactive sweep styling is consolidated in the ANIMATION SYSTEM below. */

.nav-link:hover,
.nav-link.active {
    color: var(--gold);
}

.nav-link.active::after {
    content: "";
    position: absolute;
    bottom: 4px;
    left: 10px;
    right: 10px;
    height: 1px;
    background: var(--gold);
}

.nav-contact {
    border: 1px solid var(--gold);
    color: var(--gold);
    padding: 11px 20px;
    margin-left: 14px;
}

.menu-toggle {
    display: none;
    background: none;
    border: 1px solid var(--line);
    padding: 12px;
    cursor: pointer;
}

.menu-toggle span {
    display: block;
    width: 22px;
    height: 2px;
    margin: 4px 0;
    background: var(--gold);
}

/* HERO -------------------------------------------------- */

.hero {
    min-height: 630px;
    position: relative;
    display: flex;
    align-items: center;
    border-bottom: 1px solid var(--line);
    /* Readable headline without obscuring the Damascus texture. */
    background: linear-gradient(
        90deg,
        rgba(4, 4, 4, 0.68) 0%,
        rgba(7, 7, 7, 0.33) 45%,
        rgba(10, 10, 10, 0.08) 100%
    );
}

.hero-content {
    padding-block: 100px 135px;
}

.hero h1 {
    font-size: clamp(43px, 5.4vw, 84px);
    line-height: 1.12;
    text-transform: uppercase;
    letter-spacing: 0.11em;
    margin: 22px 0 20px;
    font-weight: 700;
}

.hero h1 span {
    display: block;
}

.hero-descriptor {
    font-size: clamp(10px, 1vw, 14px);
    letter-spacing: 0.21em;
    text-transform: uppercase;
    margin-bottom: 35px;
}

.hero-descriptor span {
    color: var(--gold);
    margin: 0 10px;
}

.outline-button {
    display: inline-flex;
    justify-content: space-between;
    align-items: center;
    gap: 45px;
    border: 1px solid var(--gold);
    padding: 15px 26px;
    min-height: 51px;
    color: var(--gold);
    font-size: 12px;
    letter-spacing: 0.19em;
    text-transform: uppercase;
}

.outline-button:hover {
    box-shadow: 0 0 20px rgba(229, 168, 59, 0.15);
}

.sweep-link,
.section-card,
.project-tile,
.footer-link {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.scroll-cue {
    position: fixed;
    bottom: 26px;
    right: max(32px, calc((100vw - var(--content-width)) / 2));
    color: var(--gold);
    text-transform: uppercase;
    letter-spacing: 0.2em;
    font-size: 11px;
}

.scroll-cue span {
    display: block;
    text-align: center;
    font-size: 24px;
}

/* THREE MAIN SECTIONS ----------------------------------- */

.sections {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 15px;
    padding-top: 18px;
}

.section-card {
    min-height: 235px;
    background-color: rgba(13, 13, 13, 0.79);
    padding: 26px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    border: 1px solid var(--line);
    /* Hover transforms are defined once in the animation section. */
}


.card-number {
    color: var(--gold);
    font-size: 11px;
    letter-spacing: 0.2em;
}

.section-card h2 {
    margin: 15px 0 5px;
    color: var(--gold);
    text-transform: uppercase;
    font-size: 22px;
    letter-spacing: 0.18em;
}

.card-arrow {
    color: var(--gold);
    font-size: 26px;
    line-height: 1;
}

.section-card p {
    color: var(--muted);
    font-size: 14px;
    max-width: 290px;
    margin-top: auto;
    margin-bottom: 0;
}

/* PROJECT LIBRARY --------------------------------------- */

.project-section {
    padding-block: 100px 115px;
}

.section-heading h2 {
    margin: 8px 0;
    font-size: clamp(32px, 4vw, 55px);
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.section-heading > p:last-child {
    color: var(--muted);
    max-width: 650px;
}

.project-grid {
    margin-top: 35px;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
}

.empty-state {
    grid-column: 1 / -1;
    border: 1px solid var(--line);
    background: linear-gradient(120deg, rgba(24, 24, 24, 0.94), rgba(10, 10, 10, 0.88));
    padding: clamp(35px, 5vw, 65px);
}

.empty-state h3 {
    margin: 15px 0;
    color: var(--cream);
    font-size: clamp(24px, 3vw, 38px);
}

.empty-state p {
    color: var(--muted);
}

.project-tile {
    background: rgba(20, 20, 20, 0.92);
    border: 1px solid var(--line);
    padding: 22px;
    /* Hover transforms are defined once in the animation section. */
}


.project-tile img {
    width: 100%;
    aspect-ratio: 16 / 10;
    object-fit: cover;
    margin-bottom: 15px;
}

.project-tile h3 {
    color: var(--gold);
    font-size: 23px;
}

.project-tile p {
    color: var(--muted);
}

/* INNER PAGES ------------------------------------------- */

.inner-hero {
    min-height: 78vh;
    background: linear-gradient(90deg, rgba(5,5,5,.60), rgba(5,5,5,.18));
}

.inner-content {
    padding-block: 95px 110px;
}

.inner-content h1 {
    margin: 12px 0;
    font-size: clamp(48px, 7vw, 90px);
    letter-spacing: 0.07em;
    text-transform: uppercase;
}

.inner-lead {
    color: var(--muted);
    font-size: 18px;
    max-width: 720px;
}

.reading-panel {
    max-width: 840px;
    background: rgba(16, 16, 16, 0.86);
    border: 1px solid var(--line);
    padding: clamp(26px, 5vw, 60px);
    margin: 42px 0;
}

.reading-panel h2 {
    color: var(--gold);
    margin-top: 35px;
}

.reading-panel h2:first-child {
    margin-top: 0;
}

.reading-panel p,
.reading-panel li {
    color: var(--muted);
}

.project-hero-image {
    display: block;
    width: 100%;
    height: auto;
    margin-bottom: 30px;
}

/* FOOTER ------------------------------------------------ */

.site-footer {
    min-height: 100px;
    padding-block: 28px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
    border-top: 1px solid var(--line);
    color: var(--muted);
    font-size: 11px;
    letter-spacing: 0.13em;
    text-transform: uppercase;
}

.footer-link {
    padding: 10px;
    color: var(--gold);
}

/* MOTION ------------------------------------------------ */

.reveal {
    animation: slide-up 0.8s both;
}

.reveal:nth-child(2) {
    animation-delay: 0.1s;
}

.reveal:nth-child(3) {
    animation-delay: 0.2s;
}

.reveal:nth-child(4) {
    animation-delay: 0.3s;
}

@keyframes slide-up {
    from {
        opacity: 0;
        transform: translateY(18px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* RESPONSIVE -------------------------------------------- */

@media (max-width: 950px) {
    .menu-toggle {
        display: block;
    }

    .main-nav {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        padding: 18px 32px 28px;
        flex-direction: column;
        align-items: stretch;
        background: #111;
        border-bottom: 1px solid var(--line);
    }

    .main-nav.is-open {
        display: flex;
    }

    .nav-contact {
        margin-left: 0;
        text-align: center;
    }

    .sections {
        grid-template-columns: 1fr;
    }

    .section-card {
        min-height: 190px;
    }

    .project-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 600px) {
    .container {
        width: min(calc(100% - 36px), var(--content-width));
    }

    .nav-row {
        min-height: 74px;
    }

    .brand {
        font-size: 11px;
        letter-spacing: 0.06em;
    }

    .hero {
        min-height: 560px;
    }

    .hero-content {
        padding-block: 85px 110px;
    }

    .hero h1 {
        font-size: clamp(32px, 9vw, 54px);
        letter-spacing: 0.06em;
    }

    .hero-descriptor {
        line-height: 2.3;
    }

    .hero-descriptor span {
        margin-inline: 3px;
    }

    .project-grid {
        grid-template-columns: 1fr;
    }

    .site-footer {
        flex-direction: column;
        text-align: center;
    }

    /* On narrow screens, keep the same single non-repeating texture. */
    body::before {
        background-position: 60% center;
    }
}

@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }

    *,
    *::before,
    *::after {
        animation: none !important;
        transition: none !important;
    }
}


/* ==================================================================
   TRUE MATTE-GOLD SWEEP + CENTERED SCALE — V2
   ==================================================================

   Previous issue: a ::before overlay had z-index: -1, allowing it to
   disappear behind each element's opaque background. The text changed
   color anyway, making the interaction look instantaneous.

   Fix: animate a GOLD BACKGROUND LAYER directly. It is always rendered
   BEHIND the text and ABOVE the element's original background-color.
   At rest its width is 0%. Hover progressively increases it to 100%.
   No pseudo-element stacking context, hidden overlay, JS, or hover jump.

   The background and whole element's scale use smooth interpolated
   transitions. The scale happens from the CENTER, never one edge.

   Edit only these settings to tune the effect.
   ================================================================== */

:root {
    --sweep-gold-dark: #796039;            /* Brushed edge of the bar */
    --sweep-gold-mid: #b18a50;             /* Main matte gold */
    --sweep-gold-bright: #c49c5a;          /* Subtle leading highlight */
    --sweep-duration: 490ms;
    --sweep-ease: cubic-bezier(.45, 0, .55, 1);
    --sweep-fill-ease: linear;             /* Steady, visible left-to-right travel */
    --menu-hover-scale: 1.08;             /* 108%, entire link centered */
    --card-hover-scale: 1.035;            /* Cards slightly gentler */
    --sweep-on-gold: #1b170f;             /* Dark text once gold arrives */
}

/* All links, buttons and cards share the same REAL moving fill.
   background-size animates continuously from zero to full width. */
.nav-link,
.sweep-link,
.section-card,
.project-tile,
.footer-link,
.menu-toggle {
    position: relative;
    transform: scale(1);
    transform-origin: 50% 50%;
    background-image: linear-gradient(
        95deg,
        var(--sweep-gold-dark) 0%,
        var(--sweep-gold-mid) 60%,
        var(--sweep-gold-bright) 100%
    );
    background-repeat: no-repeat;
    background-position: left center;
    background-size: 0% 100%;
    transition:
        background-size var(--sweep-duration) var(--sweep-fill-ease),
        transform var(--sweep-duration) var(--sweep-ease),
        color 190ms ease,
        border-color 300ms ease,
        box-shadow 300ms ease;
    will-change: background-size, transform;
}

/* Nav and card enlargement does NOT change layout width or push siblings. */
.nav-link:is(:hover, :focus-visible),
.sweep-link:is(:hover, :focus-visible),
.footer-link:is(:hover, :focus-visible),
.menu-toggle:is(:hover, :focus-visible) {
    background-size: 100% 100%;
    transform: scale(var(--menu-hover-scale));
    z-index: 5;
}

.section-card:is(:hover, :focus-visible),
.project-tile:is(:hover, :focus-visible) {
    background-size: 100% 100%;
    transform: scale(var(--card-hover-scale));
    z-index: 5;
    border-color: var(--sweep-gold-bright);
    box-shadow: 0 12px 32px rgba(0, 0, 0, .32);
}

/* Keep labels readable while the gold fill is in motion.
   Wait for the sweep to travel most of the way before darkening text. */
.nav-link:is(:hover, :focus-visible),
.footer-link:is(:hover, :focus-visible),
.outline-button:is(:hover, :focus-visible) {
    color: var(--sweep-on-gold);
    transition:
        background-size var(--sweep-duration) var(--sweep-fill-ease),
        transform var(--sweep-duration) var(--sweep-ease),
        color 175ms ease 270ms,
        border-color 300ms ease,
        box-shadow 300ms ease;
}

/* The active nav item should also show its full gold fill. */
.nav-link.active:is(:hover, :focus-visible) {
    color: var(--sweep-on-gold);
}

/* Large cards sweep without relying on an invisible ::before layer.
   A delayed text transition preserves contrast once filled. */
.section-card h2,
.section-card p,
.section-card .card-arrow,
.section-card .card-number,
.project-tile h3,
.project-tile p {
    transition: color 180ms ease;
}

.section-card:is(:hover, :focus-visible) h2,
.section-card:is(:hover, :focus-visible) p,
.section-card:is(:hover, :focus-visible) .card-arrow,
.section-card:is(:hover, :focus-visible) .card-number,
.project-tile:is(:hover, :focus-visible) h3,
.project-tile:is(:hover, :focus-visible) p {
    color: var(--sweep-on-gold);
    transition: color 175ms ease 270ms;
}

/* An existing intro reveal keyframe controls transform of the CTA.
   Turn it off for the interactive link, so CSS hover scaling wins. */
.outline-button.reveal {
    animation: none;
    opacity: 1;
}

/* The homepage brand has three colored spans: avoid low-contrast gold
   letters after the matte-gold fill reaches the right edge. */
.brand:is(:hover, :focus-visible) > span {
    color: var(--sweep-on-gold);
    transition: color 175ms ease 270ms;
}

.brand > span {
    transition: color 180ms ease;
}

/* Mobile hamburger: gold sweeps beneath the three strokes.
   The strokes morph into an X when expanded. */
.menu-toggle {
    overflow: hidden;
}

.menu-toggle span {
    position: relative;
    transition:
        transform 400ms var(--sweep-ease),
        opacity 160ms ease,
        background-color 180ms ease;
}

.menu-toggle:is(:hover, :focus-visible) span {
    background-color: var(--sweep-on-gold);
    transition: background-color 175ms ease 270ms,
                transform 400ms var(--sweep-ease), opacity 160ms ease;
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) {
    transform: translateY(6px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
    opacity: 0;
    transform: scaleX(0);
}

.menu-toggle[aria-expanded="true"] span:nth-child(3) {
    transform: translateY(-6px) rotate(-45deg);
}

/* Mobile navigation: animate a real opening panel; don't toggle
   display: none, because that cannot transition smoothly. */
@media (max-width: 950px) {
    .main-nav {
        display: flex;
        max-height: 0;
        visibility: hidden;
        opacity: 0;
        overflow: hidden;
        pointer-events: none;
        padding-top: 0;
        padding-bottom: 0;
        transform: translateY(-12px);
        transform-origin: top center;
        transition:
            max-height 440ms var(--sweep-ease),
            opacity 330ms ease,
            transform 440ms var(--sweep-ease),
            padding 440ms var(--sweep-ease),
            visibility 440ms;
    }

    .main-nav.is-open {
        display: flex;
        max-height: 560px;
        visibility: visible;
        opacity: 1;
        pointer-events: auto;
        padding-top: 18px;
        padding-bottom: 28px;
        transform: translateY(0);
    }

    /* Full-width mobile rows enlarge from their center, gently enough
       that they don't get clipped by the edges of the screen. */
    .main-nav .nav-link:is(:hover, :focus-visible) {
        transform: scale(1.025);
    }

    .section-card:is(:hover, :focus-visible) {
        transform: scale(1.02);
    }
}

/* Accessibility: no motion when the OS setting requests less motion. */
@media (prefers-reduced-motion: reduce) {
    .nav-link,
    .sweep-link,
    .section-card,
    .project-tile,
    .footer-link,
    .scroll-cue,
    .menu-toggle,
    .section-card h2,
    .section-card p,
    .section-card .card-arrow,
    .section-card .card-number,
    .project-tile h3,
    .project-tile p,
    .menu-toggle span,
    .main-nav {
        transition: none !important;
        animation: none !important;
        will-change: auto;
    }
}


/* ================================================================
   PORTFOLIO REFINEMENTS — CONTACT + SCROLL CUE, OCTOBER 2026
   ================================================================
   Gold fill duration: --sweep-duration (now 490ms, previously 650ms)
   Menu scale remains centered and gradual as before.
   Scroll cue fades once page is scrolled beyond 160px.
   Reduced motion preference is respected below.
   ================================================================ */

/* Hide menu card numbering (also removed from the HTML). */
.card-number {
    display: none;
}

/* The SCROLL cue follows the user's viewport (position: fixed above).
   It is excluded from gold-fill menu styles on purpose.
   A separate transform creates uniform, centered hover enlargement.
   The inner element pulses while the outer link handles scroll fading. */
.scroll-cue {
    z-index: 8;
    opacity: 1;
    visibility: visible;
    transform: scale(1);
    transform-origin: 50% 50%;
    background: none;
    background-size: auto;
    color: var(--gold);
    transition:
        opacity 340ms ease,
        visibility 340ms ease,
        transform var(--sweep-duration) var(--sweep-ease);
}

.scroll-cue:is(:hover, :focus-visible) {
    transform: scale(var(--menu-hover-scale));
    background: none;
    color: var(--gold);
}

.scroll-cue-pulse {
    display: block;
    animation: scroll-cue-breathe 2s ease-in-out infinite;
}

.scroll-arrow {
    display: block;
    text-align: center;
    font-size: 24px;
}

@keyframes scroll-cue-breathe {
    0%, 100% { opacity: .28; }
    50% { opacity: 1; }
}

.scroll-cue:is(:hover, :focus-visible) .scroll-cue-pulse {
    animation-play-state: paused;
    opacity: 1;
}

.scroll-cue.is-hidden {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
}

/* CONTACT PAGE — readable, responsive two-panel layout. */
.contact-page {
    min-height: calc(100vh - 185px);
}

.contact-page .inner-content {
    padding-block: clamp(58px, 7vw, 100px) 100px;
}

.contact-page h1 {
    margin-bottom: 12px;
}

.contact-page .inner-lead {
    margin-bottom: 0;
}

.contact-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.12fr) minmax(0, .88fr);
    gap: 22px;
    margin-top: 42px;
}

.contact-panel {
    min-width: 0;
    background: rgba(13, 13, 13, .88);
    border: 1px solid var(--line);
    padding: clamp(24px, 3vw, 42px);
}

.contact-kicker {
    color: var(--gold);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: .25em;
    text-transform: uppercase;
    margin: 0;
}

.contact-panel h2 {
    font-size: clamp(22px, 2.3vw, 32px);
    text-transform: uppercase;
    letter-spacing: .08em;
    line-height: 1.25;
    margin: 12px 0 29px;
}

.contact-detail {
    padding: 18px 0;
    border-top: 1px solid rgba(229, 168, 59, .24);
}

.contact-detail-label {
    display: block;
    color: var(--muted);
    letter-spacing: .2em;
    text-transform: uppercase;
    font-size: 11px;
    margin-bottom: 8px;
}

.contact-detail-link {
    display: inline-block;
    max-width: 100%;
    overflow-wrap: anywhere;
    font-size: clamp(16px, 1.55vw, 21px);
    color: var(--cream);
    border-bottom: 1px solid transparent;
    transition: color 200ms ease, border-color 200ms ease;
}

.contact-detail-link:hover,
.contact-detail-link:focus-visible {
    color: var(--gold);
    border-bottom-color: var(--gold);
}

.contact-hint,
.availability-note {
    color: var(--muted);
    font-size: 13px;
    line-height: 1.7;
    margin: 25px 0 0;
}

.availability-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    border-top: 1px solid rgba(229, 168, 59, .24);
    padding: 21px 0;
}

.availability-row h3 {
    font-size: 15px;
    text-transform: uppercase;
    letter-spacing: .1em;
    margin: 0 0 5px;
}

.availability-row p {
    font-size: 13px;
    margin: 0;
    color: var(--muted);
}

.availability-status {
    color: #d4b47c;
    font-size: 13px;
    max-width: 160px;
    text-align: right;
    line-height: 1.45;
}

.contact-back {
    margin-top: 34px;
}

@media (max-width: 800px) {
    .contact-layout { grid-template-columns: 1fr; }
    .availability-status { max-width: none; }
}

@media (max-width: 420px) {
    .availability-row { align-items: flex-start; }
    .availability-status { max-width: 140px; }
}

@media (prefers-reduced-motion: reduce) {
    .scroll-cue-pulse {
        animation: none !important;
        opacity: 1 !important;
    }
    .scroll-cue {
        transition: none !important;
    }
}
